import{_ as r,l as o,o as e,c as s,v as l,p as n,x as i,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"EUV 掩模多层与缺陷","description":"","frontmatter":{"title":"EUV 掩模多层与缺陷","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-mask-defects.md","filePath":"litho/euv-mask-defects.md","lastUpdated":1789023840000}'),d={name:"litho/euv-mask-defects.md"};function c(m,a,B,A,u,f){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="euv-掩模多层与缺陷" tabindex="-1">EUV 掩模多层与缺陷 <a class="header-anchor" href="#euv-掩模多层与缺陷" aria-label="Permalink to &quot;EUV 掩模多层与缺陷&quot;">​</a></h1><div class="epigraph"><p>EUV 版是 Mo/Si 多层膜上的反射镜再加吸收体；埋在膜堆里的坑和包，pellicle 挡不住，印出来是相位缺陷。</p><footer>—— 据 Bakshi, EUV Lithography 对空白版与缺陷的讨论；防护膜与量产接口见 ASML 公开材料</footer></div><p><a href="/litho/pellicle-transmission">上一课</a>（薄膜透过率与热）。在此之上，颗粒放到离焦薄膜上，降低掩模面落尘的打印概率。缺口是：空白版在镀多层膜时就已经可能埋进坑、包和颗粒——它们改变布拉格相位，吸收体画得再对也会在晶圆上留下暗点或亮点。本课钉 EUV 反射掩模的缺陷分类。<a href="/litho/asml-nxe">NXE</a> 如何把这张版用到 0.33 NA 的量产场，是下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 透射版的缺陷主要在铬/MoSi 图形层，修镀、挖修有一套。EUV 先要一块 Mo/Si 周期多层的空白版当反射镜，再在上面做吸收体图形。<a href="/litho/euv-multilayer-mirror">多层膜镜</a>课写过布拉格反射；本课的缺口是这块镜不完美时会发生什么。衬底或膜堆中的高度误差 \\(\\Delta h\\) 变成相位 \\(4\\pi n\\Delta h/\\lambda\\) 量级（反射双程），13.5 nm 下几个纳米的坑就够致命。</p><p>Pellicle 只挡后来落在膜上的颗粒，不挡已经埋进空白版的缺陷，也不挡吸收体图形缺陷。无膜阶段更是把两类风险叠在一起。量产要的是空白版缺陷密度、吸收体缺陷检测、以及哪些缺陷可以用吸收体补偿图案盖住。</p><h3 id="相位缺陷与振幅缺陷" tabindex="-1">相位缺陷与振幅缺陷 <a class="header-anchor" href="#相位缺陷与振幅缺陷" aria-label="Permalink to &quot;相位缺陷与振幅缺陷&quot;">​</a></h3><p>埋藏坑/包主要是相位型：反射波前局部扭曲，空中像出现不可用的暗或亮。吸收体多一块或少一块主要是振幅型（也带一点相位），行为更接近 DUV 的铬缺陷，但仍在反射几何与阴影下。两类的检测：深紫外看表面往往看不见埋藏相位，需要光化波段（actinic）或高灵敏表面形貌加多层仿真。</p><p><span class="marginnote">补偿打印：有时在缺陷上方挪动或改吸收体，让局部剂量回到规格。这是掩模厂与 OPC 的联合动作，不是扫描机「对缺陷自动对焦」。能补的是弱缺陷，不是任意大坑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>空白版：超光滑衬底、缺陷检查、再镀 Mo/Si，镀后再检。吸收体：沉积、电子束或多束写入、刻蚀、再检。光化缺陷检测与光化成像显微镜（AIMS EUV 一类）在 13.5 nm 上看打印后果，避免「可见光看见、EUV 看不见」或反过来。</p><p>晶圆厂侧：重复场缺陷指向掩模；随机缺陷指向胶与颗粒。Pellicle 把后者部分转成可换膜。掩模寿命还受氢环境、碳污染和吸收体溅射限制，清洁与 DGL 课已经给了气体环境，本课只要求缺陷账与那套环境分开记。</p><h3 id="与-m3d-的边界" tabindex="-1">与 M3D 的边界 <a class="header-anchor" href="#与-m3d-的边界" aria-label="Permalink to &quot;与 M3D 的边界&quot;">​</a></h3><p><a href="/litho/mask-3d-effect">掩模 3D</a> 是吸收体厚度的系统电磁效应，OPC 默认要吃。本课的缺陷是局部偏离设计的相位/振幅点。系统阴影不是缺陷；缺陷不是用加厚吸收体就能定义掉的。SMO 优化光瞳也不消灭空白版坑。</p>',14)),(e(),n(h,null,{default:i(()=>[p(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLANK%5B%22Mo%2FSi%20%E7%A9%BA%E7%99%BD%E7%89%88%22%5D%20--%3E%20BURY%5B%22%E5%9F%8B%E8%97%8F%E5%9D%91%E5%8C%85%3A%20%E7%9B%B8%E4%BD%8D%E7%BC%BA%E9%99%B7%22%5D%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20AMP%5B%22%E5%A4%9A%2F%E5%B0%91%E5%90%B8%E6%94%B6%E4%BD%93%3A%20%E6%8C%AF%E5%B9%85%E7%BC%BA%E9%99%B7%22%5D%0A%20%20PEL%5B%22pellicle%22%5D%20--%3E%20PART%5B%22%E5%8F%AA%E6%8C%A1%E4%BA%8B%E5%90%8E%E8%90%BD%E5%B0%98%22%5D%0A%20%20BURY%20--%3E%20PRINT%5B%22%E6%99%B6%E5%9C%86%E9%87%8D%E5%A4%8D%E7%BC%BA%E9%99%B7%22%5D%0A%20%20AMP%20--%3E%20PRINT%0A%20%20PART%20--%3E%20PRINT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布拉格条件对膜周期和界面锐度敏感。局部周期被坑扰乱，反射率掉或相位跳，投影物镜把它成像为晶圆上的剂量洞或旁瓣。因为是反射，小高度误差比透射版更毒。扫描场里每次经过同一掩模坐标都印同一缺陷，所以重复性是诊断指纹。</p><p>吸收体边缘的随机缺口表现为 CD 或桥连，叠上 EUV 随机胶效应时，要靠重复性区分掩模与光子统计。下一课的 NXE 产能叙事包含掩模可用性：没有够低的空白版缺陷密度，0.33 NA 的光学分辨率兑现不成良率。</p><p>供应链分段：基板 → 多层镀膜 → blank 检验 → 吸收体图形化 → 图形检验 → 可选 pellicle。相位缺陷往往不可修，只能报废 blank 或用图案移位把缺陷藏进不打印区——版图与缺陷图的匹配是 EUV 特有的数据步骤。6 英寸版、\\(4\\times\\) 缩比下，掩模上的几何尺寸到晶圆除以 4，但相位缺陷的打印阈值不是简单的几何缩小。</p><p><span class="marginnote">投影物镜镜子也是 Mo/Si，缺陷同样致命，但镜子不图形化。<a href="/litho/euv-multilayer-mirror">多层膜镜</a>讲反射率；本课讲带吸收体图案的 reticule。不要把镜头疵点统计和掩模 blank 良率混成一张表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不编造某代空白版缺陷密度的内部规格。也不把 CNT pellicle 写成已经取消掩模检测。High-NA 掩模侧角度更大，阴影与缺陷打印阈值都要重写，那是 EXE 课的附件。后课默认：说到 EUV 掩模，先分空白版相位缺陷、吸收体缺陷、pellicle 上颗粒三类。</p><p>多层膜界面粗糙同时贡献 flare（上一计量课）和局部缺陷衬度。中频粗糙偏散射底座，孤立大坑偏可打印点；规格要分空间频率，不能用一个 RMS 数打天下。空白版供应商与掩模厂的检测地图必须能对到扫描场坐标，否则重复缺陷无法闭环。</p><p><span class="marginnote">AIMS 一类光化工具看的是等效空中像，不是 SEM 上的吸收体形貌。形貌干净仍可能相位致命，这是 EUV 相对 DUV 铬版最容易漏检的一层。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 版 = 多层反射空白版 + 吸收体；缺陷分埋藏相位与图形振幅。</li><li>Pellicle 不保护镀膜时埋进去的坑包。</li><li>光化检测才能看见 13.5 nm 的打印后果。</li><li>弱缺陷或可用吸收体补偿；重复场缺陷是掩模指纹。</li><li>下一课把这张版放进 NXE 0.33 NA 的量产场。</li><li>出处：Bakshi, <em>EUV Lithography</em>；ASML pellicle / 掩模公开材料。</li></ul>',11))])}const P=r(d,[["render",c]]);export{_ as __pageData,P as default};
